// Validar y estructurar datos de entrada
const input = $input.all()[0].json;

console.log('🔍 DEBUG - Input recibido:', JSON.stringify(input, null, 2));

// Extraer datos con valores por defecto
const dealName = input.deal || input.body?.deal;
const updates = input.updates || input.body?.updates || {};
const actividad = input.actividad || input.body?.actividad;
const completarActividad = input.completar_actividad || input.body?.completar_actividad || false;

// Validación básica
if (!dealName) {
  console.error('❌ Error: El campo "deal" es obligatorio');
  throw new Error('El campo "deal" es obligatorio');
}

console.log('✅ Validación exitosa para deal:', dealName);

// Preparar datos validados
const validated = {
  deal_name: dealName,
  mrr: updates.mrr || null,
  stage_id: updates.stage_id || null,
  probabilidad: updates.probabilidad || null,
  fecha_cierre: updates.fecha_cierre || null,
  nota: updates.nota || null,
  actividad: actividad || null,
  completar_actividad: completarActividad,
  // Mapeo de etapas
  stage_mapping: {
    "1": 104, "2": 22, "3": 23, "4": 24, "5": 25, "6": 26
  }
};

console.log('📋 Datos validados:', JSON.stringify(validated, null, 2));

return [validated];

// CÓDIGO DEFENSIVO: Extraer deal de nodo Pipedrive nativo
// NOTA: Los nodos nativos de Pipedrive devuelven el deal directamente en $json
const searchResults = $input.all()[0].json;
const validatedData = $('Validar Entrada').all()[0].json;

console.log('🔍 DEBUG - Pipedrive Native Node Response:');
console.log(JSON.stringify(searchResults, null, 2));

let deal = null;

try {
  // Nodo nativo: El deal viene directamente en $json
  if (searchResults.id) {
    deal = searchResults;
    console.log('✅ Deal obtenido de nodo nativo Pipedrive');
  }
  // Fallback: por si acaso tiene estructura data
  else if (searchResults.data && Array.isArray(searchResults.data) && searchResults.data.length > 0) {
    deal = searchResults.data[0];
    console.log('✅ Estructura detectada: data[] (fallback)');
  }
  else if (searchResults.data && searchResults.data.items && Array.isArray(searchResults.data.items)) {
    if (searchResults.data.items.length > 0) {
      deal = searchResults.data.items[0].item || searchResults.data.items[0];
      console.log('✅ Estructura detectada: data.items[].item (fallback)');
    }
  }
} catch (error) {
  console.error('❌ Error procesando estructura:', error);
}

// Validar que tenemos un deal válido
if (!deal || !deal.id) {
  console.error('❌ ESTRUCTURA NO RECONOCIDA O DEAL NO ENCONTRADO:');
  console.error(JSON.stringify(searchResults, null, 2));
  throw new Error(`Deal "${validatedData.deal_name}" no encontrado en Pipedrive.`);
}

console.log('✅ Deal extraído exitosamente:', {
  id: deal.id,
  title: deal.title || deal.name || 'Sin título'
});

return [{
  json: {
    deal_id: deal.id,
    deal_title: deal.title || deal.name || validatedData.deal_name,
    ...validatedData
  }
}];

// CÓDIGO DEFENSIVO: Verificar productos de nodo nativo
// NOTA: Nodo nativo Pipedrive con dealId devuelve deal product attachments
const allItems = $input.all();

console.log('🔍 DEBUG - Get Products Response (nodo nativo):');
console.log('Total items recibidos:', allItems.length);

if (allItems.length > 0) {
  console.log('📊 Primer producto:', JSON.stringify(allItems[0].json, null, 2));
}

let hasProducts = false;

if (allItems && allItems.length > 0) {
  // El nodo nativo con returnAll devuelve múltiples items
  hasProducts = true;
  console.log(`📊 Productos encontrados: ${allItems.length}`);
} else {
  console.log('📊 No se encontraron productos');
}

console.log(`✅ Tiene productos: ${hasProducts}`);

// Retornar el primer producto con flag hasProducts
if (hasProducts) {
  return [{ json: { ...allItems[0].json, hasProducts: true } }];
} else {
  return [{ json: { hasProducts: false } }];
}

// CÓDIGO DEFENSIVO: Extraer AMBOS IDs necesarios para actualizar producto
// IMPORTANTE: Necesitamos el attachment_id Y el catalog product_id
const productData = $json;
const dealData = $('Extraer Deal ID').first().json;

console.log('🔍 DEBUG - Extracting Product IDs from native node:');
console.log('Product data completa:', JSON.stringify(productData, null, 2));
console.log('Deal ID:', dealData.deal_id);

let attachmentId = null;
let catalogProductId = null;

// El nodo nativo devuelve:
// - id: deal_product_attachment_id (para el endpoint)
// - product_id: catalog product_id (para el payload)
if (productData.id) {
  attachmentId = productData.id;
  console.log('✅ Product Attachment ID extraído:', attachmentId);
} else {
  console.error('❌ No se pudo extraer attachment ID');
  throw new Error('Attachment ID not found in response');
}

if (productData.product_id) {
  catalogProductId = productData.product_id;
  console.log('✅ Catalog Product ID extraído:', catalogProductId);
} else {
  console.error('❌ No se pudo extraer catalog product_id');
  throw new Error('Catalog product_id not found in response');
}

console.log('✅ Datos completos para actualizar producto:');
console.log('  - Deal ID:', dealData.deal_id);
console.log('  - Attachment ID (URL):', attachmentId);
console.log('  - Catalog Product ID (payload):', catalogProductId);
console.log('  - Nuevo MRR:', dealData.mrr);

return [{
  json: {
    attachment_id: attachmentId,
    catalog_product_id: catalogProductId,
    ...dealData
  }
}];

// Preparar request para actualizar producto en deal
const dealData = $json;

console.log('🔍 DEBUG - Preparando actualización de producto:');
console.log('  Deal ID:', dealData.deal_id);
console.log('  Attachment ID (para URL):', dealData.attachment_id);
console.log('  Catalog Product ID (para payload):', dealData.catalog_product_id);
console.log('  Nuevo MRR:', dealData.mrr);

// Validar que tenemos todos los datos necesarios
if (!dealData.deal_id) {
  throw new Error('deal_id no está definido');
}
if (!dealData.attachment_id) {
  throw new Error('attachment_id no está definido');
}
if (!dealData.catalog_product_id) {
  throw new Error('catalog_product_id no está definido - REQUERIDO por Pipedrive API');
}
if (!dealData.mrr) {
  console.warn('⚠️ WARNING: mrr es null o undefined, saltando actualización');
  return [$input.item];
}

console.log('✅ Datos validados, listo para actualizar');
console.log('📤 Payload que se enviará:');
console.log('  - product_id:', dealData.catalog_product_id, '(REQUERIDO)');
console.log('  - item_price:', dealData.mrr);
console.log('  - quantity: 1');

return [$input.item];

// Logging de respuesta de actualización de producto
const response = $json;

console.log('🎯 DEBUG - Respuesta de actualización de producto:');
console.log('Status Code:', $execution.metadata?.statusCode || 'N/A');
console.log('Response completa:', JSON.stringify(response, null, 2));

if (response.success === false || response.error) {
  console.error('❌ ERROR en actualización:');
  console.error(JSON.stringify(response, null, 2));
} else if (response.success === true || response.data) {
  console.log('✅ Producto actualizado exitosamente en Pipedrive');
  if (response.data && response.data.item_price) {
    console.log('💰 Nuevo precio confirmado:', response.data.item_price);
  }
} else {
  console.warn('⚠️ Respuesta inesperada:', JSON.stringify(response, null, 2));
}

return [$input.item];

// Logging antes de crear nota
const dealData = $('Extraer Deal ID').first().json;

console.log('📝 DEBUG - Preparando creación de nota:');
console.log('  Deal ID:', dealData.deal_id);
console.log('  Nota:', dealData.nota);
console.log('  Nota !== null:', dealData.nota !== null);
console.log('  Nota !== "":', dealData.nota !== '');

if (!dealData.nota || dealData.nota === '') {
  console.warn('⚠️ WARNING: Nota está vacía o null');
} else {
  console.log('✅ Nota válida, procediendo a crear');
}

return [$input.item];

// Logging de respuesta de creación de nota
const response = $json;

console.log('📝 DEBUG - Respuesta de creación de nota:');
console.log('Response:', JSON.stringify(response, null, 2));

if (response.success !== undefined && response.success === false) {
  console.error('❌ ERROR al crear nota:');
  console.error(JSON.stringify(response, null, 2));
} else {
  console.log('✅ Nota creada exitosamente');
}

return [$input.item];

// Mapear tipos de actividad
const activityTypes = {
  "call": "call",
  "meeting": "meeting",
  "task": "task",
  "deadline": "deadline",
  "email": "email",
  "lunch": "lunch"
};

const dealData = $('Extraer Deal ID').first().json;
const actividad = dealData.actividad;

console.log('🔍 DEBUG - Preparando actividad:', JSON.stringify(actividad, null, 2));

const activityType = activityTypes[actividad.tipo] || "task";

console.log('✅ Actividad preparada:', {
  subject: actividad.titulo,
  type: activityType,
  date: actividad.fecha
});

return [{
  json: {
    ...dealData,
    activity_subject: actividad.titulo,
    activity_type: activityType,
    activity_due_date: actividad.fecha
  }
}];

const deal = $('Extraer Deal ID').first().json;

console.log('🎉 Workflow completado exitosamente para deal:', deal.deal_id);

return [{
  json: {
    success: true,
    message: "Deal actualizado exitosamente",
    deal: {
      id: deal.deal_id,
      title: deal.deal_title,
      actualizaciones_aplicadas: {
        mrr: deal.mrr !== null,
        etapa: deal.stage_id !== null,
        probabilidad: deal.probabilidad !== null,
        fecha_cierre: deal.fecha_cierre !== null,
        nota_agregada: deal.nota !== null,
        actividad_creada: deal.actividad !== null,
        actividades_completadas: deal.completar_actividad
      }
    },
    timestamp: new Date().toISOString()
  }
}];

const validatedData = $('Validar Entrada').first().json;

console.error('❌ Deal no encontrado:', validatedData.deal_name);

return [{
  json: {
    success: false,
    error: "Deal no encontrado",
    message: `No se encontró ningún deal con el nombre "${validatedData.deal_name}" en Pipedrive`,
    timestamp: new Date().toISOString()
  }
}];
